ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'SchoolOs_Testing_Pack'
PACKS=[]
def pack(code,title,roles,needs):
 p=dict(code=code,title=title,roles=roles,needs=needs,cases=[]);PACKS.append(p);return p
def c(p,title,role,steps,expect,needs='',special=''):
 p['cases'].append(dict(id=p['code']+'-'+str(len(p['cases'])+1).zfill(2),title=title,role=role,steps=steps.split('|'),expect=expect,needs=needs,special=special))
p=pack('01','Landing page and signing in','Everyone; new school owner','A signed-out browser, two controlled email inboxes, and the school address from the coordinator.')
