 w=csv.writer(f);w.writerow(['Case','Packet','Feature','Test','Use role','Extra preparation','Special condition','Assigned tester','Result','Problem number','Retest result'])
 for p in PACKS:
  for case in p['cases']:w.writerow([case['id'],p['code'],p['title'],case['title'],case['role'],case['needs'],case['special'],'','','',''])
